#include "construction/BlueprintTemplateCompiler.hpp"
#include <algorithm>
namespace elysium::construction {StampPlan compileBlueprint(const BlueprintTemplate&t,const StableIdAllocator&alloc,const IntersectionProbe&probe,bool survival){StampPlan o{};if(t.schemaVersion!=1||!t.id){o.issues.push_back({0,"schema_or_id_invalid",Intersection::Obstructed});return o;}std::vector<std::pair<std::uint32_t,const BlueprintIntent*>>order;for(std::uint32_t i=0;i<t.intents.size();++i)order.push_back({i,&t.intents[i]});std::sort(order.begin(),order.end(),[](auto&a,auto&b){auto*x=a.second,*y=b.second;return std::tie(x->z,x->y,x->x,x->kind,x->content,a.first)<std::tie(y->z,y->y,y->x,y->kind,y->content,b.first);});for(auto [idx,x]:order){if(x->containsLiveInventory||x->containsFuel||x->containsAmmo||x->containsInProgressCycle){o.issues.push_back({idx,"forbidden_live_instance_state",Intersection::Obstructed});continue;}auto inter=probe?probe(*x):Intersection::Clear;if(inter==Intersection::Obstructed){o.issues.push_back({idx,"terrain_obstructed",inter});continue;}if(inter!=Intersection::Clear)o.issues.push_back({idx,inter==Intersection::Replace?"replace": "excavate",inter});StableId sid=(x->kind==IntentKind::Machine||x->kind==IntentKind::Prefab)?alloc(idx):0;if((x->kind==IntentKind::Machine||x->kind==IntentKind::Prefab)&&!sid){o.issues.push_back({idx,"stable_id_allocation_failed",Intersection::Obstructed});continue;}o.intents.push_back({sid,*x});if(survival&&x->content&&x->amount){auto&v=o.cost[x->content];if(v>UINT64_MAX-x->amount)v=UINT64_MAX;else v+=x->amount;}}o.accepted=std::none_of(o.issues.begin(),o.issues.end(),[](auto&i){return i.intersection==Intersection::Obstructed;});return o;}}
